#!/usr/bin/env node

import { gzipSync } from "node:zlib";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = path.join(root, "data", "scripture", "web-search-index.json");
const outputPath = path.join(root, "src", "lib", "generated-web-search-index.ts");
const source = await readFile(sourcePath);
const encoded = gzipSync(source, { level: 9 }).toString("base64");
const output = `// Generated by scripts/generate-scripture-search-bundle.mjs. Do not edit manually.\nexport const webSearchIndexGzipBase64 = ${JSON.stringify(encoded)};\n`;

await writeFile(outputPath, output, "utf8");
console.log(`Embedded Scripture search corpus: ${source.length} bytes -> ${encoded.length} base64 characters.`);
